import React, { Suspense, lazy } from 'react';
import ReactDOM from 'react-dom/client';
import { Provider } from 'react-redux';
import { configureStore } from "@reduxjs/toolkit";
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import { WagmiConfig, createConfig, configureChains } from 'wagmi';
import { mainnet, sepolia } from 'wagmi/chains';
import { publicProvider } from 'wagmi/providers/public';
import { RainbowKitProvider, getDefaultWallets } from '@rainbow-me/rainbowkit';
import '@rainbow-me/rainbowkit/styles.css';
import './index.css';
import Navigation from './components/Navigation';
import DynamicPagePadding from './components/DynamicPagePadding';

import Sparkles from './components/effects/Sparkles';
import CursorTrail from './components/effects/CursorTrail';
import AnimatedMushroomCursor from './components/effects/AnimatedMushroomCursor';
import { SporeContainer } from './components/effects/SporeEffect';
import BottomMushroomLayer from './components/BottomMushroomLayer';
import BrowserDetectionBanner from './components/BrowserDetectionBanner';
import wallet from "./store/walletSlice";
import ritual from "./store/ritualSlice";
import provider from "./store/reducers/provider";
import tokens from "./store/reducers/tokens";
import amm from "./store/reducers/amm";
import crowdsale from "./store/reducers/crowdsale";

const LandingPage = lazy(() => import('./components/LandingPage'));
const DailyShrooms = lazy(() => import('./components/pages/DailyShrooms'));
const CrossBreeding = lazy(() => import('./components/pages/CrossBreeding'));
const Governance = lazy(() => import('./components/pages/Governance'));
const AltarBurn = lazy(() => import('./components/pages/AltarBurn'));
const Donate = lazy(() => import('./components/pages/Donate'));
const Swap = lazy(() => import('./components/pages/Swap'));
const Contact = lazy(() => import('./components/pages/Contact'));
const AdminPanel = lazy(() => import('./components/pages/AdminPanel'));
const NotFound404 = lazy(() => import('./components/pages/NotFound404'));

// Define custom localhost chain with correct Hardhat chain ID
const hardhatLocal = {
  id: 31337,
  name: 'Hardhat Local',
  network: 'hardhat',
  nativeCurrency: {
    decimals: 18,
    name: 'Ether',
    symbol: 'ETH',
  },
  rpcUrls: {
    default: { http: ['http://127.0.0.1:8545'] },
    public: { http: ['http://127.0.0.1:8545'] },
  },
  testnet: true,
};

// Configure Redux store
export const store = configureStore({
  reducer: {
    wallet,
    ritual,
    provider,
    tokens,
    amm,
    crowdsale
  },

  middleware: (getDefaultMiddleware) =>
    getDefaultMiddleware({
      serializableCheck: {
        // Ignore these action types
        ignoredActions: ['provider/setProvider', 'tokens/setContracts', 'amm/setContract', 'crowdsale/setCrowdsaleContract'],
        // Ignore these field paths in all actions
        ignoredActionPaths: ['payload.connection', 'payload.contract', 'payload.0', 'payload.1'],
        // Ignore these paths in the state
        ignoredPaths: ['provider.connection', 'tokens.contracts', 'amm.contract', 'crowdsale.contract'],
      },
    }),
});

// Configure chains & providers for Wagmi
const { chains, publicClient, webSocketPublicClient } = configureChains(
  [hardhatLocal, sepolia, mainnet],
  [publicProvider()]
);

// Configure RainbowKit wallets
const { connectors } = getDefaultWallets({
  appName: 'Ethereal Offering',
  projectId: 'YOUR_PROJECT_ID', // Get this from WalletConnect Cloud
  chains
});

// Create Wagmi config
const wagmiConfig = createConfig({
  autoConnect: true,
  connectors,
  publicClient,
  webSocketPublicClient,
});

// Main App component with routing
function App() {
  return (
    <Router basename={process.env.PUBLIC_URL}>
      {/* Browser/Mobile Detection Banners */}
      <BrowserDetectionBanner />

      {/* Visual Effects - Applied to all pages */}
      <DynamicPagePadding />
      <Sparkles />
      <CursorTrail />
      <AnimatedMushroomCursor />
      <SporeContainer />
      <BottomMushroomLayer />

      <Navigation />
      <Suspense fallback={<div style={{ padding: 24, textAlign: 'center', color: '#a78bfa' }}>🍄 Loading…</div>}>
        <Routes>
          <Route path="/" element={<LandingPage />} />
          <Route path="/daily-shrooms" element={<DailyShrooms />} />
          <Route path="/cross-breeding" element={<CrossBreeding />} />
          <Route path="/governance" element={<Governance />} />
          <Route path="/altar" element={<AltarBurn />} />
          <Route path="/donate" element={<Donate />} />
          <Route path="/swap" element={<Swap />} />
          <Route path="/contact" element={<Contact />} />
          <Route path="/admin" element={<AdminPanel />} />
          <Route path="*" element={<NotFound404 />} />
        </Routes>
      </Suspense>
    </Router>
  );
}

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(
  <React.StrictMode>
    <WagmiConfig config={wagmiConfig}>
      <RainbowKitProvider chains={chains}>
        <Provider store={store}>
          <App />
        </Provider>
      </RainbowKitProvider>
    </WagmiConfig>
  </React.StrictMode>
);
